import React, { useRef, useEffect } from 'react';
import { Send, Users } from 'lucide-react';
import './StudentTips.css';

const StudentTips = ({ language }) => {
  const publicUrl = process.env.PUBLIC_URL || '';
  const chatEndRef = useRef(null);

  // Текст раздела и интродакшен (чтобы борд смотрелся шире)
  const introData = {
    RU: {
      title: "Советы от студентов",
      p1: "Мы просто спросили иностранных студентов, которые уже живут в Тюмени: «Что бы ты сказал новичку?»",
      p2: "Опрошенными стали обычные ребята. Такие же, как те, которые приехали с чемоданом, боялись холода, не знали, как тут вообще выживать, а потом втянулись и сказали: «А ничего так город».",
      p3: "Мы собрали их ответы. Ничего не придумывали. Вот что они советуют — и от чего предостерегают."
    },
    EN: {
      title: "Student Tips",
      p1: "We simply asked international students who already live in Tyumen: 'What would you say to a newcomer?'",
      p2: "The respondents were ordinary guys. Just like those who arrived with a suitcase, were afraid of the cold, did not know how to survive here, and then got drawn into it and said: 'It's actually a nice city'.",
      p3: "We collected their answers. We didn't make anything up. Here is what they advise — and what they warn against."
    }
  };

  const tipsData = {
    RU: [
      "Не недооценивай гололёд! Упасть в первый день - классика 😂",
      "Обязательно реши вопрос с жильём ДО приезда сюда",
      "Скачай 2ГИС, город большой, Google Карты иногда глючат",
      "Гуляй по набережной и Мосту Влюблённых, там классно)",
      "Не бойся общаться — люди тут реально открытые и всегда помогут!",
      "Бери тёплую одежду, но не весь гардероб из дома",
      "Ребята, не откладывайте оформление документов! Делайте сразу!",
      "Рассчитывай время на автобус в отдалённых районах (лучше приходить заранее)",
      "И самое главное: не стоит быть закрытым в общежитии :)"
    ],
    EN: [
      "Don't underestimate the ice! Falling on day 1 is a classic 😂",
      "Make sure you resolve your housing issues BEFORE arrival",
      "Download 2GIS app, the city is big, Google Maps can be glitchy here",
      "Walk along the Embankment and Lovers' Bridge, it's cool there)",
      "Don't be afraid to socialize — people are truly open and ready to help!",
      "Bring warm clothes, but not your entire wardrobe",
      "Guys, don't postpone paperwork! Do everything ASAP!",
      "Plan bus times wisely in remote districts (come early)",
      "Most importantly: don't lock yourself inside the dorm :)"
    ]
  };

  const uiText = {
    RU: {
      chatName: "ТюмГУ Адаптация",
      members: "137 участников",
      placeholder: "Поделись мнением о Тюмени...",
      wip: "(в разработке)"
    },
    EN: {
      chatName: "UTMN Adaptation",
      members: "137 members",
      placeholder: "Share your opinion...",
      wip: "(WIP)"
    }
  };

  const currentIntro = introData[language] || introData.RU;
  const currentTips = tipsData[language] || tipsData.RU;
  const currentUI = uiText[language] || uiText.RU;

  // Автоскролл до первого сообщения (эффект живого чата)
  useEffect(() => {
    if(chatEndRef.current) {
      chatEndRef.current.scrollTop = 0; // Начнём читать с верхних сообщений
    }
  }, []);

  return (
    <section id="tips" className="student-tips section">
      <div className="container">

        {/* Секция: Верхний текстовый блок */}
        <div className="tips-intro-section">
          <h2 className="section-title">{currentIntro.title}</h2>
          <div className="tips-intro-text">
            <p>{currentIntro.p1}</p>
            <p>{currentIntro.p2}</p>
            <p className="highlight-text">{currentIntro.p3}</p>
          </div>
        </div>

        {/* Секция: Нижний Flex-контейнер (Отзыв слева, Телефон справа) */}
        <div className="tips-content-flex">
          
          <div className="testimonial-side">
            <div className="testimonial-card">
              <div className="testimonial-quote">“</div>
              <p className="testimonial-text">
                {language === 'RU' 
                  ? "Ожидания оправдались. Тюмень — класс" 
                  : "Expectations met. Tyumen is awesome"}
              </p>
              <p className="testimonial-author">
                {language === 'RU' 
                  ? "— респондент из Екатеринбурга" 
                  : "— respondent from Yekaterinburg"}
              </p>
              <div className="testimonial-divider"></div>
              <p className="testimonial-note">
                {language === 'RU'
                  ? "Проект помогает разрушать стереотипы о Тюмени и Сибири там, где государственные новости почти не работают. Университеты получают простой и бесплатный инструмент адаптации иностранцев."
                  : "The project breaks down stereotypes about Tyumen and Siberia where official news barely work. Universities gain a simple and free tool to adapt foreign students."}
              </p>
            </div>
          </div>

          <div className="smartphone-side">
            <div className="smartphone-mockup-container">
              {/* Котеус заглядывающий за телефон */}
              <img 
                src={`${publicUrl}/images/kotak_tips.webp`} 
                alt="Котеус с советами" 
                className="cat4-tips-phone" 
              />
              
              <div className="smartphone-device">
                <div className="smart-notch"></div>
                
                <div className="chat-header">
                  <div className="chat-avatar">
                    <Users size={20} color="var(--accent)" strokeWidth={2.5}/>
                  </div>
                  <div className="chat-info">
                    <strong>{currentUI.chatName}</strong>
                    <span>{currentUI.members}</span>
                  </div>
                </div>

                <div className="chat-body" ref={chatEndRef}>
                  {currentTips.map((tip, idx) => {
                    const isRight = idx % 2 !== 0; // "Шахматное" отображение сообщений для визуальной динамики
                    return (
                      <div key={idx} className={`chat-message ${isRight ? 'msg-right' : 'msg-left'}`}>
                        <div className="chat-bubble">
                          {tip}
                        </div>
                      </div>
                    );
                  })}
                </div>

                <div className="chat-footer">
                  <div className="chat-input-fake">
                    <span className="fake-text">{currentUI.placeholder}</span>
                    <span className="wip-badge">{currentUI.wip}</span>
                  </div>
                  <div className="chat-send-btn disabled">
                    <Send size={18} strokeWidth={2.5} />
                  </div>
                </div>
              </div>
            </div>
          </div>

        </div>

      </div>
    </section>
  );
};

export default StudentTips;